update_rule.pseudocode:
if policy.enabled and policy.start_day <= day <= policy.end_day:
  for seg in ['early','majority','laggard']:
    if policy.target_segment_code == 0 or (policy.target_segment_code == 1 and seg=='early') or (policy.target_segment_code == 2 and seg=='majority') or (policy.target_segment_code == 3 and seg=='laggard'):
      price_adjustment[seg] = policy.incentive_amount
    else:
      price_adjustment[seg] = 0.0
else:
  price_adjustment[seg] = 0.0 for all seg
emit signals.price_adjustment_per_segment = price_adjustment
